// lib/demo/emulator.js
//
// The static (Vercel) build has no backend. This module answers the same
// requests the Express API would, from data/demo/*.json, with the same
// response envelopes. It is used in two places so the demo behaves the same
// on the server and in the browser:
//   - lib/data/catalog.js   (server components)
//   - lib/api/client.js     (axios adapter for client components + admin)
//
// Writes are refused with 403 and a clear message. The one exception is the
// demo admin login, which lets a visitor look around the dashboard.
//
// Fixtures are generated by amkahon-back/scripts/buildFixtures.js from the
// same seed the database uses. Do not hand edit them.
import { DEMO_ADMIN } from "@/lib/config";
import categories from "@/data/demo/categories.json";
import hero from "@/data/demo/hero.json";
import heroItems from "@/data/demo/hero-items.json";
import sections from "@/data/demo/homepage-sections.json";
import navbar from "@/data/demo/navbar.json";
import products from "@/data/demo/products.json";
import reviews from "@/data/demo/reviews.json";
import { adminEmpty, adminGet } from "@/lib/demo/adminDemo";
import shippingRates from "@/data/demo/shipping-rates.json";
import faqs from "@/data/demo/faqs.json";
import storefront from "@/data/demo/storefront.json";

export const DEMO_TOKEN = "demo-static-token";
const DEMO_USER = {
    _id: "000000000000000000000d30",
    name: "Demo Admin",
    email: DEMO_ADMIN.email,
    role: "admin",
    isEmailVerified: true,
    isDemo: true,
};

const ok = (data) => ({ status: 200, data });
const fail = (status, message) => ({ status, data: { success: false, message } });
const DEMO_WRITE =
    "This is a demo site. Nothing can be changed here, but everything works on the live store.";

// ─── catalogue helpers ────────────────────────────────────────────────────────
const allCats = categories.data;

const subtreeIds = (param) => {
    if (!param) return null;
    const root = allCats.find((c) => c._id === param || c.slug === param);
    if (!root) return new Set();
    const ids = new Set([root._id]);
    let grew = true;
    while (grew) {
        grew = false;
        for (const c of allCats) {
            if (c.parentCategory && ids.has(c.parentCategory._id) && !ids.has(c._id)) {
                ids.add(c._id);
                grew = true;
            }
        }
    }
    return ids;
};

const sorters = {
    displayOrder: (a, b) => a.displayOrder - b.displayOrder,
    newest: (a, b) => b.displayOrder - a.displayOrder,
    price_asc: (a, b) => (a.price ?? 0) - (b.price ?? 0),
    price_desc: (a, b) => (b.price ?? 0) - (a.price ?? 0),
    popularity: (a, b) => b.purchaseCount - a.purchaseCount,
    rating: (a, b) => b.averageRating - a.averageRating,
};

/** GET /api/products — same params and envelope as productController.getProducts */
export function listProducts(params = {}) {
    const page = Math.max(1, parseInt(params.page, 10) || 1);
    const limit = Math.max(1, parseInt(params.limit, 10) || 12);
    let rows = products.filter((p) => p.isActive);

    const ids = subtreeIds(params.category);
    if (ids) rows = rows.filter((p) => ids.has(p.category?._id) || ids.has(p.subCategory?._id));
    if (params.search) {
        const q = String(params.search).toLowerCase();
        rows = rows.filter((p) => `${p.name} ${p.nameBn} ${p.description}`.toLowerCase().includes(q));
    }
    if (["in_stock", "pre_order", "out_of_season"].includes(params.availability)) {
        rows = rows.filter((p) => p.availability === params.availability);
    }
    if (params.wholesale === "true") rows = rows.filter((p) => p.wholesale?.enabled);
    if (params.inStock === "true") rows = rows.filter((p) => p.stock > 0);
    if (params.minPrice) rows = rows.filter((p) => p.price >= Number(params.minPrice));
    if (params.maxPrice) rows = rows.filter((p) => p.price != null && p.price <= Number(params.maxPrice));

    const sortBy = sorters[params.sortBy] ? params.sortBy : "displayOrder";
    rows = [...rows].sort(sorters[sortBy]);

    const total = rows.length;
    return {
        success: true,
        products: rows.slice((page - 1) * limit, page * limit),
        total,
        totalPages: Math.ceil(total / limit),
        currentPage: page,
        limit,
        sortBy,
        sortOrder: params.sortOrder || "asc",
    };
}

export const productBySlug = (slug) => products.find((p) => p.slug === slug) || null;

function related({ productId, categoryId, limit = 4 }) {
    const self = products.find((p) => p._id === productId);
    const cat = categoryId || self?.category?._id;
    const rows = products
        .filter((p) => p._id !== productId && (p.category?._id === cat || p.subCategory?._id === cat))
        .slice(0, Number(limit) || 4);
    return { success: true, products: rows, total: rows.length };
}

// ─── router ───────────────────────────────────────────────────────────────────
/**
 * @param {string} method  GET/POST/...
 * @param {string} path    path after /api, e.g. "/products/slug/x"
 * @param {object} params  query params
 * @param {object} body    parsed JSON body
 * @param {string} token   bearer token, if any
 * @returns {{status:number, data:any}}
 */
// Same season rules as the API (amkahon-back services/storefront.js).
const SEASON = storefront.activeSeason || "all";
const inSeason = (list) => !list?.length || list.includes("all") || list.includes(SEASON);
const seasonHero = () => {
    const fits = (i) => !i.season || i.season === "all" || i.season === SEASON;
    const items = ["desktop", "mobile"].flatMap((d) => {
        const forDevice = hero.items.filter((i) => i.deviceType === d);
        const picked = forDevice.filter(fits);
        return picked.length ? picked : forDevice;
    });
    return { ...hero, items };
};

export function handle(method, path, params = {}, body = {}, token = null) {
    const m = method.toUpperCase();
    const p = path.split("?")[0].replace(/\/+$/, "") || "/";

    if (m === "GET") {
        if (p === "/products") return ok(listProducts(params));
        if (p === "/products/featured") return ok({ success: true, products: products.filter((x) => x.isFeatured) });
        if (p === "/products/homepage-sections") return ok({ ...sections, sections: sections.sections.filter((x) => inSeason(x.seasons)) });
        if (p === "/products/related") return ok(related(params));
        if (p.startsWith("/products/slug/")) {
            const product = productBySlug(decodeURIComponent(p.slice("/products/slug/".length)));
            return product ? ok({ success: true, product }) : fail(404, "Product not found");
        }
        if (p.startsWith("/products/")) {
            const product = products.find((x) => x._id === p.slice("/products/".length));
            return product ? ok({ success: true, product }) : fail(404, "Product not found");
        }
        if (p === "/reviews/featured") return ok(reviews.featured);
        if (p.startsWith("/reviews/product/")) {
            const id = p.slice("/reviews/product/".length);
            return ok(reviews.byProduct[id] || { success: true, reviews: [], total: 0, totalPages: 0, currentPage: 1, ratingStats: [], averageRating: 0, totalReviews: 0 });
        }
        if (p === "/categories") return ok(categories);
        if (p === "/navbar/config") return ok(navbar);
        if (p === "/hero") return ok(seasonHero());
        if (p === "/storefront") return ok({ success: true, activeSeason: SEASON, content: storefront.seasons[SEASON] || {}, story: storefront.story || {} });
        if (p === "/storefront/faqs") {
            const list = faqs.faqs.filter((f) => f.isActive && inSeason(f.seasons) && (params.homepage !== "true" || f.showOnHomepage));
            return ok({ success: true, faqs: list.map(({ _id, question, answer }) => ({ _id, question, answer })) });
        }
        if (p === "/hero-items") return ok(heroItems);
        if (p === "/checkout/shipping-rates") return ok(shippingRates);
        if (p === "/auth/me") {
            return token === DEMO_TOKEN ? ok({ success: true, user: DEMO_USER }) : fail(401, "Not authorized");
        }
        if (p === "/auth/logout") return ok({ success: true });
        if (p === "/cart") return ok({ success: true, cart: { items: [], totalPrice: 0 } });
        if (p === "/wishlist") return ok({ success: true, wishlist: { products: [] } });
        if (p.startsWith("/admin") || p === "/categories/tree") {
            // Demo dashboard needs the demo login.
            if (token !== DEMO_TOKEN) return fail(401, "Not authorized");
            const data = adminGet(p, params);
            return ok(data ?? adminEmpty());
        }
        return fail(404, "Not available in the demo");
    }

    if (m === "POST" && p === "/auth/login") {
        if (body?.email === DEMO_ADMIN.email && body?.password === DEMO_ADMIN.password) {
            return ok({ success: true, token: DEMO_TOKEN, user: DEMO_USER });
        }
        return fail(401, `Demo login only. Use ${DEMO_ADMIN.email} / ${DEMO_ADMIN.password}`);
    }

    return fail(403, DEMO_WRITE);
}
